--
-- 本文件会：TRUNCATE hero 表 → 重新插入 127 名英雄（id 1~127 = 官网英文名首字母顺序）
-- ============================================================

SET NAMES utf8mb4;
USE dota_guide;

TRUNCATE TABLE hero;
-- 重置自增计数器：TRUNCATE 本身会重置，这里显式写一次保险
ALTER TABLE hero AUTO_INCREMENT = 1;

INSERT INTO hero (id, name, alias, `role`, pos, attr, attack, complexity, avatar, intro, tips, items, counters) VALUES
-- 1. 敌法师（敏捷 / 近战 / 复杂度1 / 1号位）【俗称：敌法、AM】
(1, '敌法师', '敌法、AM', '核心、爆发、逃生', '1号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/antimage.png', '只要给了敌法师积累力量的机会，他的碾压将无法阻挡。进，他会枯竭敌人的魔力，退，他可短距离传送。想将他逼入困境绝非易事。', '一、核心节奏是刷：前期别参团，闷头刷出核心装；二、大招对缺蓝英雄伤害爆炸，团战盯着法师打；三、最怕控制和爆发，分身斧和 BKB 保命。', '狂战斧、碎颅锤、黑皇杖、深渊之刃', '克制：法系阵容（烧蓝）；怕：控制、爆发'),
-- 2. 斧王（力量 / 近战 / 复杂度1 / 3号位）
(2, '斧王', '', '核心、控制、肉盾、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/axe.png', '一个接着一个，斧王将他的敌人斩落。作为团队的先锋，他使敌人陷入战斗，致命的旋斧会对他们的攻击作出回应。一旦敌人出现衰迹，他将挥舞着淘汰之刃挺身而出。', '一、对线期出先锋盾，站在兵线里挨打也不慌；二、中期憋跳刀（闪烁匕首），跳进人群开"狂战士之吼"嘲讽敌人，让队友跟上输出；三、大招留给残血英雄，别浪费在小兵身上。斧王最怕被远程风筝，跳刀切入时机是最需要练的地方。', '先锋盾、闪烁匕首（跳刀）、刃甲、黑皇杖（BKB）', '克制：脆皮近战、依赖普攻的核心；怕：远程风筝、百分比伤害'),
-- 3. 祸乱之源（全才 / 远程 / 复杂度2 / 5号位）【俗称：睡魔】
(3, '祸乱之源', '睡魔', '辅助、爆发、控制、肉盾', '5号位', '全才', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/bane.png', '祸乱之源掌中的控制技能让敌人们望而生畏。无论是困住敌人的传染性噩梦，还是让敌人动弹不得的魔爪，他总是能为盟友争取到歼灭敌人的时间。', '一、大招抓住敌方核心，队友集火；二、噩梦可以睡人，注意别睡队友；三、减攻让对面大哥输出大打折扣。', '秘法鞋、阿哈利姆神杖、闪烁匕首、卫士胫甲', '克制：单核（大招点控）；怕：打断、被集火'),
-- 4. 血魔（敏捷 / 近战 / 复杂度1 / 1/2号位）
(4, '血魔', '', '核心、爆发、控制、先手', '1/2号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/bloodseeker.png', '血魔可以使他的敌人陷入两难的境地。他用血祀为一片区域洗礼，迫使敌人后撤，而他冷血的大招让敌人要么原地不动，要么倒在血泊之中。', '一、被动感知低血量敌人，残血别想跑；二、血祭范围沉默，团战放好限制法系；三、大招禁足，配合队友集火。', '相位鞋、刃甲、黑皇杖、撒旦之邪力', '克制：残血收割（被动感知）；怕：控制、爆发'),
-- 5. 水晶室女（智力 / 远程 / 复杂度1 / 5号位）【俗称：冰女、CM】
(5, '水晶室女', '冰女、CM', '辅助、爆发、控制', '5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/crystal_maiden.png', '有了水晶室女，盟友的魔法将源源不断，敌人的死亡在她的减速下得到了保障，对于任何团队，她都是有力的帮手。良机出现之时，她还将发动大规模的终极技能给敌人带去毁灭。', '一、别抢大哥补刀，多用冰霜新星消耗；二、买眼做视野是生命线；三、团战站位靠后，大招别被控制打断。', '静谧之鞋、梅肯斯姆、洞察烟斗、闪烁匕首', '克制：抱团（大招）；怕：打断、突脸'),
-- 6. 卓尔游侠（敏捷 / 远程 / 复杂度1 / 1号位）【俗称：小黑、黑弓】
(6, '卓尔游侠', '小黑、黑弓', '核心、控制、推进', '1号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/drow_ranger.png', '一旦卓尔游侠箭所能及，再想逃脱绝非易事。一阵寒风吹过，敌人全部噤声，一阵冰箭射过，敌人无一幸免。', '一、站位是命：被近身会失去被动加成，保持距离；二、沉默和减速风筝近战；三、出装围绕攻速和输出，后期接管比赛。', '飓风长戟、代达罗斯之殇、黑皇杖、撒旦之邪力', '克制：近战（风筝流）；怕：突脸、跳刀切入'),
-- 7. 撼地者（力量 / 近战 / 复杂度2 / 4号位）【俗称：小牛、神牛、ES】
(7, '撼地者', '小牛、神牛、ES', '辅助、爆发、控制、先手', '4号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/earthshaker.png', '断绝敌人后路，分割敌人实力，抑或是震撼众敌脚下的大地，撼地者最擅长出其不意的袭击。就算侥幸挺过了余震，一记强大的图腾还在后面等着。', '一、沟壑封路要放得"恶心"——把敌人和退路隔开；二、大招在敌方英雄密集时伤害最高，等对面抱团再放；三、核心装备是跳刀，跳大是每个撼地者玩家的必修课。', '秘法鞋、闪烁匕首、阿哈利姆神杖、刷新球', '克制：幻象系、抱团阵容（大招人多伤害高）；怕：被先手秒、沉默'),
-- 8. 主宰（敏捷 / 近战 / 复杂度1 / 1号位）【俗称：剑圣、尤涅若】
(8, '主宰', '剑圣、尤涅若', '核心、逃生、推进', '1号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/juggernaut.png', '一阵刀光剑影过后，主宰的敌人就已被他斩落。他以剑刃的旋转切入战斗，在战场上英勇无畏，迅疾非常，敌人基本没有招架的余地，抵挡住主宰就跟从他手中逃脱一样绝非易事。', '一、剑刃风暴期间魔免，躲技能神器；二、大招无敌斩期间无敌，落单敌人必死；三、治疗守卫是团队续航，团战放好。', '碎颅锤、黑皇杖、代达罗斯之殇、深渊之刃', '克制：脆皮（无敌斩）；怕：位移躲大招、反打'),
-- 9. 米拉娜（敏捷 / 远程 / 复杂度2 / 4/5号位）【俗称：白虎、POM】
(9, '米拉娜', '白虎、POM', '核心、辅助、爆发、控制、逃生', '4/5号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/mirana.png', '米拉娜在战场的远处将致命的箭矢瞄准敌人，而她时刻准备着跃入战场。盟友可以在她的祝福下不被敌人探查，保证己方永远都在潜行。', '米拉娜（白虎）是"游走辅助"的典型：一、月神之箭射程越远眩晕越久，躲在阴影里放冷箭，配合队友的控制技能"接箭"命中率更高；二、跳跃可以躲开飞行中的弹道技能，被追时往树林里跳；三、大招群体隐身是开团/撤退神器，开大前先跟队友说好一起走。新手先把"射箭"练准。', '静谧之鞋、原力法杖、洞察烟斗、阿哈利姆神杖', '克制：脆皮、落单英雄（冷箭）；怕：真视宝石/粉（破隐身）、冲脸强控'),
-- 10. 影魔（敏捷 / 远程 / 复杂度2 / 1/2号位）【俗称：SF】
(10, '影魔', 'SF', '核心、爆发', '1/2号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/nevermore.png', '影魔无时不在俘获手下的亡魂，力量也无时不在汇聚。每一次出手，每一记精准的阴影，收下人头的同时也让他释放积聚灵魂产生的夺命冲击更具威力。', '一、影压是核心输出和补刀手段，需要大量练习；二、阵亡损失一半灵魂，别浪；三、大招贴脸释放，配合隐刀或跳刀。', '闪烁匕首、黑皇杖、代达罗斯之殇、蝴蝶', '克制：脆皮、抱团（大招贴脸）；怕：强控、突脸'),
-- 11. 变体精灵（敏捷 / 远程 / 复杂度3 / 1号位）【俗称：水人】
(11, '变体精灵', '水人', '核心、爆发、控制、肉盾、逃生', '1号位', '敏捷', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/morphling.png', '变体精灵可以转换属性来适应情势，他擅长金蝉脱壳，也能夺人性命。不论是乘着波浪从旁袭击敌人，或者在逃入迷惑性极强的复制体前使自己的生命猛增，他总是不给人击杀的希望。', '一、属性转换是核心：打架时转敏捷输出，危险时转力量保命；二、波浪形态可位移可躲技能；三、大招复制敌方英雄，以彼之道还施彼身。', '黑皇杖、蝴蝶、撒旦之邪力、代达罗斯之殇', '克制：复制克制对面大哥；怕：沉默、爆发（转属性前）'),
-- 12. 幻影长矛手（敏捷 / 近战 / 复杂度2 / 1号位）【俗称：猴子、PL】
(12, '幻影长矛手', '猴子、PL', '核心、爆发、逃生、推进', '1号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/phantom_lancer.png', '幻影长矛手操控源源不断的复制体展开攻势，让敌人应接不暇。带领着他的幻象大军，密集的攻击将撕裂敌阵，使对手喘不过气来，还能派出分身向敌方推进，一旦局势不妙就运用神形百变迷惑对手，逃之夭夭。', '一、幻象迷惑敌人，真身别暴露；二、冲撞减速追击；三、怕 AOE 清幻象，注意对面阵容。', '辉耀、黑皇杖、蝴蝶、恐鳌之心', '克制：拖后期、单核（幻象海）；怕：AOE、真眼'),
-- 13. 帕克（智力 / 远程 / 复杂度2 / 2号位）【俗称：精灵龙、仙女龙】
(13, '帕克', '精灵龙、仙女龙', '爆发、控制、逃生、先手', '2号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/puck.png', '帕克脑海中有很多跟敌人开玩笑的恶作剧，它也因此天生就拥有将敌人搅得莫名其妙的本事。它可以传送到伤人的光球身上进行短距离跳跃，挥洒大量粉尘将敌人沉默。还没等敌人开始反应，帕克早已逃之夭夭。', '一、相位转移躲技能，操作上限高；二、大招缠绕群体控制；三、技能连招需要练习，新手慎重。', '闪烁匕首、阿哈利姆神杖、黑皇杖、玲珑心', '克制：脆皮（控制爆发）；怕：沉默、强控'),
-- 14. 帕吉（力量 / 近战 / 复杂度2 / 4号位）【俗称：屠夫】
(14, '帕吉', '屠夫', '爆发、控制、肉盾、先手', '4号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/pudge.png', '帕吉每次精准地甩出标志性的长钩时都将恐惧深深印入敌人心中。他将敌人拉到身边，用屠刀大卸八块，而自己从阵亡的敌人身上获得了额外的力量和攻击力，不遑多时就会成为势不可挡的杀手。', '一、肉钩是弹道技能，要预判敌人走位，蹲在树林和阴影里出钩命中率更高；二、钩中之后立刻开腐烂贴身输出，再用大招"肢解"咬住，一套连招脆皮必死；三、被动每杀一人叠加力量，越到后期越肉。钩不中千万别气馁，每一个屠夫高手都是用海量空钩喂出来的。', '相位鞋、先锋盾、阿哈利姆神杖、洞察烟斗', '克制：脆皮法师、落单英雄；怕：净化类技能（清腐烂）、高爆发'),
-- 15. 雷泽（敏捷 / 远程 / 复杂度1 / 1/3号位）【俗称：剃刀、电魂】
(15, '雷泽', '剃刀、电魂', '核心、爆发、肉盾、推进', '1/3号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/razor.png', '掌控着致命的闪电风暴，雷泽在战场上横冲直撞。他展开电气的等离子环烧灼敌人，与敌人链接的同时将他们的力量收为己用。', '一、静电链接偷攻击，贴住对面大哥打；二、大招追人清场；三、出装半肉，站得住才能偷。', '相位鞋、黑皇杖、撒旦之邪力、蝴蝶', '克制：物理核心（静电链接偷攻）；怕：法系爆发、风筝'),
-- 16. 沙王（全才 / 近战 / 复杂度2 / 3号位）【俗称：SK】
(16, '沙王', 'SK', '辅助、爆发、控制、逃生、先手', '3号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/sand_king.png', '能够逃过沙王伏击的寥寥无几。他从地下突袭敌人，将他们晕在原地，再操控终极技能释放出数波致命的震荡，摧毁周围的一切，而敌人的反击则被隐藏在沙暴中的他尽数躲过。', '一、核心出装是跳刀：跳进人群开大再穿刺；二、埋沙能躲技能，关键时刻保命；三、大招需要站桩施法，注意别被打断。', '闪烁匕首、黑皇杖、阿哈利姆神杖、希瓦的守护', '克制：抱团（地震大招）；怕：反隐、沉默、打断'),
-- 17. 风暴之灵（智力 / 远程 / 复杂度2 / 2号位）【俗称：蓝猫】
(17, '风暴之灵', '蓝猫', '核心、爆发、控制、逃生、先手', '2号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/storm_spirit.png', '风暴之灵从未错失一场战斗。将自己压缩于一道闪电中在战场中穿梭，他运用爆炸性的残影和饱含电荷的攻击从四面八方奇袭敌人，而敌人还在手忙脚乱的时候他已经不知去向。', '一、大招消耗蓝量，蓝量管理是核心；二、飞入人群爆发，打完飞走；三、装备围绕回蓝，血精石经典。', '血精石、黑皇杖、希瓦的守护、玲珑心', '克制：脆皮、机动收割（大招全场飞）；怕：沉默、强控、打断'),
-- 18. 斯温（力量 / 近战 / 复杂度1 / 1号位）
(18, '斯温', '', '核心、爆发、控制、肉盾、先手', '1号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/sven.png', '斯温总是渴望投入战斗。他在作战中击晕聚拢的敌人，而他一旦激发了终极技能就会大幅提升攻击力，挥舞几下手中的巨剑就能将敌人一一斩落。', '打法就是一个字——"刷"：一、对线期稳补刀，优先出狂战斧（分裂攻击刷钱神器），刷野清线两不误；二、中期出跳刀和黑皇杖（BKB，免疫魔法控制），开大招跳脸，两刀一个脆皮；三、大招冷却时避战打钱，没大不打团。斯温最怕被放风筝，跳刀切入的时机就是他的全部学问。', '狂战斧、闪烁匕首、黑皇杖、代达罗斯之殇', '克制：脆皮阵容（一刀清场）；怕：放风筝、控制链'),
-- 19. 小小（力量 / 近战 / 复杂度2 / 2/3号位）【俗称：石头人、山岭巨人】
(19, '小小', '石头人、山岭巨人', '核心、爆发、控制、肉盾、推进、先手', '2/3号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/tiny.png', '随着战斗的推进，小小的身材和力量都将成长到惊人的地步，而他的威力也会非常可怕。他向敌人们投掷英雄，或者让他们在山崩下昏迷。只要给他机会发挥出完全的实力，他就能摧枯拉朽般毁灭敌方的基地。', '一、经典连招：抓住敌人→扔向队友或防御塔；二、"山崩 + 投掷"的组合伤害爆炸，练好顺序；三、后期变巨拆塔飞快，团战打不过就带线偷塔。', '闪烁匕首、黑皇杖、强袭胸甲、代达罗斯之殇', '克制：脆皮（抓扔秒人）、建筑（拆塔）；怕：控制链'),
-- 20. 复仇之魂（敏捷 / 远程 / 复杂度1 / 4/5号位）【俗称：VS】
(20, '复仇之魂', 'VS', '辅助、爆发、控制、逃生、先手', '4/5号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/vengefulspirit.png', '众人永远能感受到复仇之魂的存在，不管她是生是死。她可以与周围任何英雄交换位置，击晕敌人，不幸阵亡还能让凶手的输出大打折扣。有她在场，给敌人带去的混乱将源源不断。', '复仇之魂（VS）是最简单直接的辅助之一：一、魔法箭是指向性眩晕（点谁晕谁，不会空），线上稳定先手；二、恐怖波动减敌人护甲还能开视野，开团前先放一发；三、大招移形换位可以把对面核心换进我方人堆，也能把被集火的队友换出来——注意别把自己换进绝境；四、被动让她死后还能继续放技能和输出几秒，阵亡换掉对面核心也不亏。', '静谧之鞋、原力法杖、微光披风、洞察烟斗', '克制：脆皮核心（换位先手）；怕：换位后自己落单被集火'),
-- 21. 风行者（全才 / 远程 / 复杂度2 / 2/3号位）【俗称：风行、风女】
(21, '风行者', '风行、风女', '核心、辅助、爆发、控制、逃生', '2/3号位', '全才', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/windrunner.png', '风行者身法轻灵多变，总是在寻找出手的角度。她要么张弓射出强力致命的一箭，要么将敌人束缚在一起，向他们射出箭雨，风行者永远都是那么雷厉风行。', '一、强力击蓄力远程爆发，练好预判；二、风行逃生追击；三、大招对单体输出爆炸，适合切脆皮。', '黑皇杖、代达罗斯之殇、蝴蝶、希瓦的守护', '克制：单挑、单抓（集中火力）；怕：控制、打断'),
-- 22. 宙斯（智力 / 远程 / 复杂度1 / 2号位）
(22, '宙斯', '', '核心、爆发', '2号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/zuus.png', '宙斯面前所有人都无处遁形，他召唤的一道惊雷会让周围的英雄暴露无遗，放出的弧形闪电可以游遍附近的敌人，而号令的可怕霹雳将打击一切仇敌。无论敌人何在，宙斯都将找到他们。', '一、大招全图收割残血，多关注小地图；二、技能爆发高，秒脆皮；三、自身极脆，站位和视野最重要。', '动力鞋、阿哈利姆神杖、刷新球、希瓦的守护', '克制：脆皮、全图收割（雷神之怒）；怕：突脸、强控'),
-- 23. 昆卡（力量 / 近战 / 复杂度2 / 2/3号位）【俗称：船长】
(23, '昆卡', '船长', '核心、辅助、爆发、控制、肉盾、先手', '2/3号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/kunkka.png', '昆卡总是对敌人的动向了如指掌。他可以操控一股涌流或一艘幽灵船对一个地点发动袭击，如果目标无误，他和他的盟友就能毫不费力地收拾残局。', '一、潮汐使者（水刀）溅射对线消耗很恶心，练好补刀节奏；二、"X 标记 + 洪流"的连招可以定点晕人，先练熟再谈团战；三、幽灵船冲撞后全队获得减伤，开团时机好能逆转团战。', '相位鞋、狂战斧、黑皇杖、代达罗斯之殇', '克制：脆皮、抱团（水刀溅射）；怕：沉默、被风筝'),
-- 24. 莉娜（智力 / 远程 / 复杂度1 / 2号位）【俗称：火女】
(24, '莉娜', '火女', '核心、辅助、爆发、控制', '2号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/lina.png', '极其致命的莉娜也很容易薄命，她可以毫不费力地击杀任何落单的笨蛋。每次施法后她都能获得攻击速度，运用烈焰和热闪电肃清敌人，确保没人能顶住她的袭击。', '一、技能连招龙破斩 + 光击阵，练好命中；二、大招单体爆发秒脆皮；三、后期攻速装平 A 输出，转型平滑。', '动力鞋、闪烁匕首、黑皇杖、代达罗斯之殇', '克制：脆皮（法术爆发）；怕：突脸、强控'),
-- 25. 巫妖（智力 / 远程 / 复杂度1 / 5号位）
(25, '巫妖', '', '辅助、爆发', '5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/lich.png', '在战场间飘行的同时献祭小兵，为自己的袭击补充魔法，巫妖随时可以操控减速的冰霜帮助队友消灭他们的敌人。对于蠢到聚在一起的敌人，他极富弹跳性的终极技能将确保他们的灭亡。', '一、牺牲小兵回蓝，线上续航强；二、护盾给大哥，对拼不虚；三、大招弹射敌人越多越疼，团战时机重要。', '秘法鞋、梅肯斯姆、卫士胫甲、阿哈利姆神杖', '克制：对线保护、抱团；怕：突脸、后期乏力'),
-- 26. 莱恩（智力 / 远程 / 复杂度1 / 4/5号位）【俗称：恶魔巫师】
(26, '莱恩', '恶魔巫师', '辅助、爆发、控制、先手', '4/5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/lion.png', '有莱恩在，敌人反击的机会微乎及微。一排伤人的尖刺能使人头晕目眩，强大的变形术会将敌人暂时变成人畜无害的小动物，就算手中的魔法还不够强大，他和盟友有充足的时间斩落他们的敌人。', '一、插地眩晕先手，妖术变羊；二、大招斩杀残血；三、吸小兵回蓝，续航强。', '闪烁匕首、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：脆皮（大招斩杀）；怕：突脸'),
-- 27. 暗影萨满（智力 / 远程 / 复杂度1 / 4/5号位）【俗称：小Y、萨满】
(27, '暗影萨满', '小Y、萨满', '辅助、爆发、控制、推进、先手', '4/5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/shadow_shaman.png', '暗影萨满可以为友军迅速开出一条直捣敌军基地的行进之路。运用闪电魔法打击敌人，操控妖术干扰敌军，强大的毒蛇守卫将轻松摧毁敌人的防御工事。', '一、蛇棒大招拆塔极快，推进节奏；二、变羊 + 锁链控制链完整；三、自身脆，注意站位。', '秘法鞋、阿哈利姆神杖、闪烁匕首、卫士胫甲', '克制：控制链、推塔（蛇棒）；怕：突脸、爆发'),
-- 28. 斯拉达（力量 / 近战 / 复杂度1 / 3号位）【俗称：大鱼人】
(28, '斯拉达', '大鱼人', '核心、控制、肉盾、逃生、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/slardar.png', '斯拉达在战场上蜿蜒急行，随时可以找到敌军并将其碾压。敌人将暴露无遗，防御力也会遭到粉碎，他靠近敌人后三叉戟有力的重击将重创敌人，使他们动弹不得。', '一、大招点灯能反隐，对面有隐身英雄时价值翻倍；二、冲刺接眩晕是标准先手，追人能力强；三、出装半肉，BKB 保证站场。', '相位鞋、闪烁匕首、黑皇杖、强袭胸甲', '克制：隐身英雄（大招点灯反隐）、肉盾；怕：风筝、控制'),
-- 29. 潮汐猎人（力量 / 近战 / 复杂度1 / 3号位）【俗称：潮汐】
(29, '潮汐猎人', '潮汐', '核心、爆发、控制、肉盾、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/tidehunter.png', '潮汐猎人昂首阔步地走在队伍的前面，他总是在留意出手的时机。时机来临时，他会释放毁灭性的终极技能，为盟友留下一堆头晕目眩的敌人任他们宰割。', '一、大招是全队开团信号，跳刀进场放大再接输出；二、海妖外壳被动解控，被打了别慌；三、站最前面吃技能，为队友创造输出空间。', '闪烁匕首、先锋盾、黑皇杖、刷新球', '克制：抱团（大招先手开团）；怕：沉默、大招被躲'),
-- 30. 巫医（智力 / 远程 / 复杂度1 / 4/5号位）
(30, '巫医', '', '辅助、爆发、控制', '4/5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/witch_doctor.png', '巫医可以为团队提供所需的一切。持续的治疗、眩晕和诅咒保证了团队每个人头，强大的终极技能则让他自己在舞蹈中毁灭敌人，他技能的全面实在是少有匹敌。', '一、药剂弹跳眩晕，控制足；二、大招站桩输出，注意站位；三、大招怕控制，BKB 或找好位置。', '秘法鞋、阿哈利姆神杖、黑皇杖、卫士胫甲', '克制：抱团（大招持续输出）；怕：打断、突脸'),
-- 31. 力丸（敏捷 / 近战 / 复杂度1 / 4/1号位）【俗称：隐刺、SA】
(31, '力丸', '隐刺、SA', '核心、控制、逃生', '4/1号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/riki.png', '力丸在敌人的眼皮底下潜行于战场。他仔细挑选时机，在一阵沉默的烟雾中骤然出现，敌人还未察觉之前背后已遭中伤。', '一、隐身游走抓单，烟幕沉默克制法师；二、背刺伤害高，绕后打；三、真眼反隐很克你，注意对面视野。', '相位鞋、碎颅锤、黑皇杖、否决坠饰', '克制：脆皮、法师（永久隐身）；怕：真眼、显影之尘'),
-- 32. 谜团（全才 / 远程 / 复杂度2 / 3号位）
(32, '谜团', '', '控制、推进、先手', '3号位', '全才', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/enigma.png', '谜团身怀无人不怕的终极技能，他可以召唤出使敌人动弹不得的黑洞，让友军将他们一网打尽。时常有一队虚灵体陪伴左右，他无需近身就能消灭敌人。', '一、黑洞是团战核心，等对面抱团再放；二、跳刀 + BKB 保证黑洞放出来；三、前期偏发育，注意节奏。', '闪烁匕首、黑皇杖、卫士胫甲、刷新球', '克制：抱团（黑洞）；怕：打断、被先手'),
-- 33. 修补匠（智力 / 远程 / 复杂度2 / 2号位）【俗称：TK】
(33, '修补匠', 'TK', '核心、爆发、推进', '2号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/tinker.png', '修补匠运用众多致命的器具摧毁敌人。如果他能集齐所需的资源，瞬间刷新技能的力量可以让他在各大前线引领着他的团队。', '一、刷新机制是核心，技能循环轰炸；二、全图传送支援和带线；三、操作量大，新手慎重。', '闪烁匕首、阿哈利姆神杖、希瓦的守护、玲珑心', '克制：带线、消耗（刷新轰炸）；怕：突脸、沉默'),
-- 34. 狙击手（敏捷 / 远程 / 复杂度1 / 2号位）【俗称：火枪、矮子】
(34, '狙击手', '火枪、矮子', '核心、爆发', '2号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/sniper.png', '杀人于千里之外是狙击手的绝技。固定的火力弹幕让敌人应接不暇，接着抓住时机，使出一记杀手枪将他们带走。', '一、射程是你的命，保持最远距离输出；二、大招全图收残血；三、被突脸基本等死，站位和视野最重要。', '魔龙枪、飓风长戟、代达罗斯之殇、黑皇杖', '克制：远程消耗、放风筝；怕：突脸、跳刀切入'),
-- 35. 瘟疫法师（智力 / 远程 / 复杂度1 / 2/3号位）【俗称：死灵法、NEC】
(35, '瘟疫法师', '死灵法、NEC', '核心、爆发、控制、肉盾', '2/3号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/necrolyte.png', '瘟疫法师所到之处，仇敌萎靡不振，盟友精神焕发。每次死亡脉冲都可以治疗战友，伤害敌人，一旦有敌人在他的存在下消溶，他将召出一把镰刀，延长其往生的时间。', '一、光环持续伤害，贴脸消耗；二、大招斩杀残血，克制复活类英雄；三、回血机制强，出装半肉，越打越难死。', '卫士胫甲、黑皇杖、恐鳌之心、希瓦的守护', '克制：持久战、肉盾（大招禁复活）；怕：爆发、禁疗'),
-- 36. 术士（智力 / 远程 / 复杂度1 / 5号位）
(36, '术士', '', '辅助、控制、先手', '5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/warlock.png', '召唤出他的烈狱魔像，术士为敌人们带来毁灭，将他们的防御工事摧毁殆尽。然而即使没有魔像，他吟唱暗黑魔法还能破坏敌阵，只靠一句咒语就能治疗盟友，伤害敌人，或者让敌人相互连接，共同负担受到的痛苦。', '一、致命链接让 AOE 伤害翻倍；二、大招地狱火控制输出兼备；三、团战型辅助，跟着队伍节奏。', '秘法鞋、阿哈利姆神杖、卫士胫甲、刷新球', '克制：抱团（地狱火大招）；怕：先手被秒'),
-- 37. 兽王（全才 / 近战 / 复杂度2 / 3号位）
(37, '兽王', '', '爆发、控制、肉盾、先手', '3号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/beastmaster.png', '兽王在战场上行走从来都是准备万全。他可以召唤喷毒的野猪和刺探敌情的战鹰协助狩猎，挥舞双斧劈开丛林中的树木，他震耳欲聋的咆哮将为盟友开出一条灭敌之路。', '一、老鹰别闲着，放在河道和野区关键路口当移动眼；二、大招是穿人眩晕，尽量对准敌方核心放；三、召唤的野猪可以减速留人。兽王吃节奏，多和队友沟通开团时机。', '支配头盔、阿哈利姆神杖、强袭胸甲、刷新球', '克制：脆皮、无位移英雄；怕：AOE 清召唤物'),
-- 38. 痛苦女王（智力 / 远程 / 复杂度2 / 2号位）【俗称：女王、QOP】
(38, '痛苦女王', '女王、QOP', '核心、爆发、逃生', '2号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/queenofpain.png', '痛苦女王的出手占尽先机，成群的敌人将在震耳欲聋的尖叫声中遭到毁灭。就算在猛攻中生还，敌人在逃生过程中还将被投掷的匕首减速，最终交出他的小命。', '一、闪烁切入切出，灵活输出；二、尖叫贴脸爆发，秒脆皮；三、节奏是前中期压制，后期疲软注意。', '闪烁匕首、黑皇杖、希瓦的守护、玲珑心', '克制：脆皮（爆发秒人）；怕：沉默、后期乏力'),
-- 39. 剧毒术士（全才 / 远程 / 复杂度1 / 3/4号位）
(39, '剧毒术士', '', '辅助、爆发、控制、推进、先手', '3/4号位', '全才', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/venomancer.png', '剧毒术士给敌人带来的是慢性死亡。他可以持续散布喷毒的守卫来防御领土，如果敌人靠近，他还能释放一个巨型毒云，让他们快速衰亡。', '一、毒叠加持续伤害，消耗和压制；二、大招范围剧毒，团战铺场；三、蛇棒推线推进，节奏稳健。', '秘法鞋、阿哈利姆神杖、卫士胫甲、希瓦的守护', '克制：消耗、阵地战（铺毒）；怕：爆发、切入'),
-- 40. 虚空假面（敏捷 / 近战 / 复杂度2 / 1号位）【俗称：虚空、FV】
(40, '虚空假面', '虚空、FV', '核心、控制、肉盾、逃生、先手', '1号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/faceless_void.png', '时间就是虚空假面的一切。时间经他加速可以缩短两地之间的行程，由他篡改可以消弭伤害，他还可以强行停下一片区域内的时间，毁灭他的敌人。只要给他充足的时间，他就能迎来自己的辉煌时代。', '一、大招要罩住敌人、别罩队友；二、配合队友 AOE（如撼地者）毁天灭地；三、自身前期弱，发育为主，出装攻速暴击。', '疯狂面具、漩涡、黑皇杖、代达罗斯之殇', '克制：抱团（时间结界）；怕：被秒、大招没罩好'),
-- 41. 冥魂大帝（力量 / 近战 / 复杂度1 / 1号位）【俗称：骷髅王、大帝】
(41, '冥魂大帝', '骷髅王、大帝', '核心、辅助、控制、肉盾、先手', '1号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/skeleton_king.png', '无所畏惧地向敌人大步走去，冥魂大帝击晕敌人，用他的大刀阔剑让他们心悦诚服。就算敌人稍占上风，他的终极技能可以使他再度崛起，保证他还有机会挥起宝剑。', '一、大招被动复活，打团时大胆一点，但注意复活冷却；二、出装无脑堆肉和输出，辉耀流经典；三、复活怕被"瘟疫法师"这类克制技能针对，对面选了要小心。', '臂章、辉耀、黑皇杖、恐鳌之心', '克制：持久战（两条命）；怕：瘟疫法师大招（禁复活）、控制'),
-- 42. 死亡先知（全才 / 远程 / 复杂度1 / 2/3号位）【俗称：DP】
(42, '死亡先知', 'DP', '核心、爆发、控制、推进', '2/3号位', '全才', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/death_prophet.png', '死亡先知只要释放出她的怨灵大军，敌人和他们的建筑都将不堪一击。她的虫群可以产生一波又一波的伤害，她的猛攻近乎无人能挡，在直捣敌方基地的团队中她独挑大梁。', '一、大招拆塔效率极高，节奏是开大推进；二、沉默克制法师；三、站得住才能持续输出，出装半肉。', '卫士胫甲、黑皇杖、希瓦的守护、恐鳌之心', '克制：推塔、抱团（幽灵大军）；怕：爆发、打断'),
-- 43. 幻影刺客（敏捷 / 近战 / 复杂度1 / 1号位）【俗称：幻刺、PA】
(43, '幻影刺客', '幻刺、PA', '核心、逃生', '1号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/phantom_assassin.png', '幻影刺客的猎物现身之际，就是她出手之时。她快速地接近目标，轻松地躲过攻击，残忍地收割敌人的性命。没有一丝预兆，她的任何攻击都有可能置人于死地。', '一、暴击看脸，出装围绕攻速暴击；二、隐身迷雾用来切入和逃生；三、BKB 防控制，跳脸秒脆皮。', '碎颅锤、黑皇杖、代达罗斯之殇、深渊之刃', '克制：脆皮、辅助（暴击秒人）；怕：强控、真眼反隐'),
-- 44. 帕格纳（智力 / 远程 / 复杂度2 / 4号位）【俗称：骨法】
(44, '帕格纳', '骨法', '爆发、推进', '4号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/pugna.png', '狡猾的欺诈师帕格纳在轰击敌人防御工事的同时能使他们的力量背叛他们。当他的幽冥守卫冲击周围胆敢施法的敌人时，他汲取敌人的生命，为下次突袭做好准备。', '一、幽冥守卫让法师放技能掉血；二、大招吸血救人两用；三、幽冥爆破拆塔快。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：法师（幽冥守卫反伤）；怕：突脸'),
-- 45. 圣堂刺客（敏捷 / 远程 / 复杂度2 / 2号位）【俗称：圣堂、TA】
(45, '圣堂刺客', '圣堂、TA', '核心、逃生', '2号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/templar_assassin.png', '圣堂刺客在战场上散布缓速的陷阱，她隐去自己的身形，准备好伏击她的猎物。当她跃起突击时，尖利的灵能之刃将刺穿敌人，任何反击都将在折光的护盾下消弭于无形。', '一、折光挡伤害，对拼神器；二、隐匿一击爆发高，练好节奏；三、怕持续伤害（如剧毒术士），注意对面阵容。', '闪烁匕首、黑皇杖、代达罗斯之殇、蝴蝶', '克制：脆皮（隐匿爆发）；怕：持续伤害、真眼'),
-- 46. 冥界亚龙（敏捷 / 远程 / 复杂度1 / 2/3号位）【俗称：毒龙】
(46, '冥界亚龙', '毒龙', '核心、控制、肉盾、先手', '2/3号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/viper.png', '冥界亚龙不必近身就可以喷射致命的剧毒，无论是谁都抵受不了。他周身的多种毒素可以蚕食敌人的生命，使他们行动迟缓。冥界亚龙仅仅是在表演他的拿手绝活：不断地增加剂量。', '一、对线极强，压制对面中单；二、毒液减速追杀；三、大招单点爆发，克制脆皮。', '魔龙枪、黑皇杖、希瓦的守护、恐鳌之心', '克制：线上压制、肉盾（持续毒伤）；怕：被风筝、位移'),
-- 47. 露娜（敏捷 / 远程 / 复杂度1 / 1号位）【俗称：月骑】
(47, '露娜', '月骑', '核心、爆发、推进', '1号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/luna.png', '露娜参战的速度往往飞快，她弹力十足的攻击可以将敌人粉碎。一旦陷入险境，她可以呼唤月相之力，洒下一道辉光或是一阵猛烈的月蚀，碾压顽抗的敌人。', '一、月光弹射清线极快，发育节奏好；二、大招贴脸放伤害爆炸；三、光环加攻，团战站桩输出。', '黑皇杖、蝴蝶、撒旦之邪力、代达罗斯之殇', '克制：清线快、抱团推进；怕：突脸、减甲'),
-- 48. 龙骑士（力量 / 近战 / 复杂度1 / 2/3号位）【俗称：龙骑、DK】
(48, '龙骑士', '龙骑、DK', '核心、爆发、控制、肉盾、推进、先手', '2/3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/dragon_knight.png', '当龙骑士化身为可怕的古龙形态，他面前的敌人都会不禁感到害怕。身坚甲厚又能随机应变，眩晕他的敌人并使他们烈焰焚身，他让他的盟友获得凌驾对手的胜势。', '一、没变龙时以推线和刷钱为主，别硬接团；二、变龙后带队推塔——喷火能攻击防御塔（Dota 特色）；三、出装以跳刀先手 + 输出装为主，BKB 保证变身期间不被控。', '闪烁匕首、黑皇杖、强袭胸甲、代达罗斯之殇', '克制：脆皮阵容（变龙喷火推塔）；怕：没变龙时被强开团、减甲'),
-- 49. 戴泽（全才 / 远程 / 复杂度1 / 5号位）【俗称：暗牧】
(49, '戴泽', '暗牧', '辅助、爆发、控制', '5号位', '全才', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/dazzle.png', '戴泽天生就是战场上伙伴的辅助，受伤的队友在他的保护下能将死亡撒遍敌军之内。他奇特的魔法可以编织附近的铠甲，敌人大幅衰弱之际友军将异常坚挺。', '一、浅影给残血队友，几秒不死能翻盘；二、毒波减甲配合物理输出；三、大招期间全队技能转得快。', '秘法鞋、梅肯斯姆、卫士胫甲、阿哈利姆神杖', '克制：保人、持久战（浅影续命）；怕：爆发、沉默'),
-- 50. 发条技师（力量 / 近战 / 复杂度2 / 3/4号位）【俗称：发条、机器人】
(50, '发条技师', '发条、机器人', '爆发、控制、肉盾、先手', '3/4号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/rattletrap.png', '发条技师射出钩爪使自己飞入敌人人群中，将目标隔离后用弹片冲击搅得他们晕头转向。他用实用的照明弹侦察战场，不费吹灰之力就能找到合适的目标。', '一、钩爪射程极远，抓单前先想好"钩过去打得过吗"；二、齿轮框住敌人后在里面 1v1，等队友跟上输出；三、照明弹既能开视野也能远程补刀，多用。', '闪烁匕首、阿哈利姆神杖、刃甲、恐鳌之心', '克制：脆皮法师（框住单挑）；怕：爆发、反手控制'),
-- 51. 拉席克（智力 / 远程 / 复杂度1 / 2号位）【俗称：老鹿】
(51, '拉席克', '老鹿', '核心、辅助、爆发、控制、推进', '2号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/leshrac.png', '拉席克强大的魔法可以摧枯拉朽般将敌人和他们的坚塔毁灭。灾难性的敕令让他在敌方领地中长驱直入，把握良机将大地撕裂的能力可以使敌人动弹不得，让无情的盟友将他们一一终结。', '一、技能 AOE 清线快，推塔利器；二、大招开启后贴脸输出，注意走位；三、出装半肉，站得住才有输出。', '血精石、黑皇杖、希瓦的守护、恐鳌之心', '克制：推塔、抱团（大招持续伤害）；怕：沉默、爆发'),
-- 52. 自然先知（全才 / 远程 / 复杂度2 / 3/4号位）【俗称：先知、法里奥】
(52, '自然先知', '先知、法里奥', '核心、爆发、逃生、推进', '3/4号位', '全才', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/furion.png', '无论是赶赴战场援助友军，还是累积资源准备下次突袭，自然先知仿佛无处不在。他可以随意传送到任何地方，立刻创造一群狂暴的树木为他作战，他出手的角度总是出乎敌人意料。', '一、全图传送支援和偷塔，多关注小地图；二、树人推线拆塔，牵制节奏；三、大招支援远处团战，全图存在感。', '动力鞋、阿哈利姆神杖、否决坠饰、卫士胫甲', '克制：全球流、偷塔（全图传送）；怕：被抓、真眼'),
-- 53. 噬魂鬼（力量 / 近战 / 复杂度2 / 1号位）【俗称：小狗、食尸鬼】
(53, '噬魂鬼', '小狗、食尸鬼', '核心、控制、肉盾、逃生', '1号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/life_stealer.png', '只要噬魂鬼接近了他的猎物，他连一线生机都不会给予。他可以在友方英雄和小兵体内潜伏，接近敌人时他从宿主体内爆发而出，用利爪将大惊失色的敌人撕碎。', '一、大招狂暴期间魔免，用来躲关键控制或强杀；二、感染可以钻进队友体内，配合有先手的队友"开车"进场；三、出装围绕攻速和移速，最怕被风筝，相位鞋和晕锤是核心。', '相位鞋、臂章、碎颅锤、撒旦之邪力', '克制：肉盾（百分比伤害）；怕：风筝、减速'),
-- 54. 黑暗贤者（智力 / 近战 / 复杂度1 / 3号位）【俗称：黑贤、兔子】
(54, '黑暗贤者', '黑贤、兔子', '控制、逃生、先手', '3号位', '智力', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/dark_seer.png', '足智多谋的黑暗贤者擅长操控敌人的方位。他可以创造真空，把敌人卷入盟友的攻击中，再将他们扯入复制之墙中，让敌人身受自身之力的反噬。', '一、"真空 + 复制墙"的连招是团战核心；二、离子外壳给队友或自己，追着人烫；三、团战型英雄，跟着队友节奏。', '秘法鞋、梅肯斯姆、卫士胫甲、洞察烟斗', '克制：抱团（真空 + 复制墙）；怕：沉默、打断'),
-- 55. 克林克兹（敏捷 / 远程 / 复杂度2 / 1/2号位）【俗称：骨弓、骷髅射手】
(55, '克林克兹', '骨弓、骷髅射手', '核心、逃生、推进', '1/2号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/clinkz.png', '克林克兹无形地穿梭在战场上，没人能逃过他的伏击。他的步伐和箭矢迅疾异常，只要召唤出一队炽烈同胞助阵，灼热的箭雨过后就是敌人的死亡。', '一、隐身接近脆皮一套秒，打完就走；二、大招吃小兵强化输出，打架前先吃；三、自身脆，被反隐针对时注意站位。', '动力鞋、魔龙枪、黑皇杖、代达罗斯之殇', '克制：脆皮单抓；怕：真眼反隐、爆发'),
-- 56. 全能骑士（力量 / 近战 / 复杂度1 / 5号位）【俗称：全能、OK】
(56, '全能骑士', '全能、OK', '辅助、爆发、肉盾', '5号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/omniknight.png', '作为战场前线的卫士，全能骑士总是渴望加入团队的战斗。不论是使用伤敌的魔法治疗队友，还是手握强大的战锤敲打敌人，他总是能帮助盟友免受伤害。', '一、驱逐/守护套给被控的大哥，救人一命胜造七级浮屠；二、大招全图无敌，团战关键时刻开；三、自身出团队装（梅肯斯姆、卫士胫甲），站队伍后排。', '秘法鞋、梅肯斯姆、卫士胫甲、阿哈利姆神杖', '克制：物理阵容（守护套魔免）；怕：净化类技能、爆发'),
-- 57. 魅惑魔女（智力 / 远程 / 复杂度2 / 4/5号位）【俗称：小鹿】
(57, '魅惑魔女', '小鹿', '辅助、控制、肉盾、推进', '4/5号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/enchantress.png', '近斗使人无可奈何，远战又招招致命，魅惑魔女只要出手就能刺穿敌人，她的攻击融入了魔力后敌人逃得越远，所受伤害也越高。不论是在敌人身上施加强大的减速效果，还是魅惑丛林中的生物来助战，她总是不乏制胜的手段。', '一、魅惑野怪参战，前期节奏强；二、大招伤害随距离增加，站远点打；三、怕魔法爆发，注意站位。', '动力鞋、飓风长戟、阿哈利姆神杖、卫士胫甲', '克制：物理阵容（减伤被动）；怕：法系爆发'),
-- 58. 哈斯卡（力量 / 远程 / 复杂度1 / 2号位）【俗称：神灵、神灵武士】
(58, '哈斯卡', '神灵、神灵武士', '核心、肉盾、先手', '2号位', '力量', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/huskar.png', '随着生命的不断流失，哈斯卡的杀敌能力大幅上升。他的终极技能可以瞬间移除自己和敌人的部分生命，而在濒死时他炽热的长矛已经掷得毁天灭地。', '一、核心机制是控血：血量低输出才高，但要留安全线；二、灼热之矛叠加灼烧，对线期追着对面戳；三、最怕瞬间爆发，出 BKB、撒旦（吸血）保命。注意：哈斯卡"看起来无敌"时最容易送。', '臂章、黑皇杖、撒旦之邪力、恐鳌之心', '克制：法师、低爆发英雄；怕：纯粹伤害、瞬间爆发'),
-- 59. 暗夜魔王（力量 / 近战 / 复杂度1 / 3号位）【俗称：夜魔】
(59, '暗夜魔王', '夜魔', '核心、爆发、控制、肉盾、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/night_stalker.png', '太阳一旦下山，暗夜魔王的狩猎就会开始。他冲过暗影斑驳的丛林，在缓速的虚空中捕获猎物，将他们撕成碎片。如果日出威胁到了他的笼罩，他还能使天空暗淡，延长他的袭击。', '一、晚上才是你的时间：夜晚主动抓人，白天安心发育；二、虚空能减速并沉默，抓单时先手放；三、留意游戏时间，第一个夜晚是建立优势的黄金期。', '相位鞋、闪烁匕首、黑皇杖、深渊之刃', '克制：脆皮、落单（夜晚抓人）；怕：白天疲软期、反手控制'),
-- 60. 育母蜘蛛（敏捷 / 近战 / 复杂度2 / 2/3号位）【俗称：蜘蛛、母蜘蛛】
(60, '育母蜘蛛', '蜘蛛、母蜘蛛', '核心、爆发、逃生、推进', '2/3号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/broodmother.png', '育母蜘蛛在蛛网中滑行，培育出一支蜘蛛大军直捣敌人的基地。猎物一旦靠近，她将与自己的孩子一同袭击，释放内心无法满足的狩猎天性，咬得敌人麻痹不动。', '一、蛛网范围内才是主场，别离开网打架；二、小蜘蛛推线拆塔极快，围绕一条路打；三、怕 AOE 清小蜘蛛，对面有范围伤害英雄时谨慎。', '动力鞋、阿哈利姆神杖、黑皇杖、强袭胸甲', '克制：单路压制、推塔；怕：AOE、火系范围技能'),
-- 61. 赏金猎人（敏捷 / 近战 / 复杂度1 / 4号位）【俗称：赏金】
(61, '赏金猎人', '赏金', '爆发、逃生', '4号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/bounty_hunter.png', '赏金猎人总是鬼鬼祟祟地跟在敌人后头，掌握他们的动向。一旦他的目标在战斗中阵亡，他和盟友将获得可观的收入。', '一、核心是标记：击杀带标记的敌人全队拿额外赏金；二、隐身游走骚扰对面打钱，恶心人就对了；三、别贪兵线，你是辅助。', '静谧之鞋、阿哈利姆神杖、否决坠饰、卫士胫甲', '克制：隐身游走、经济压制（标记赏金）；怕：真眼反隐、后期乏力'),
-- 62. 编织者（敏捷 / 远程 / 复杂度2 / 1号位）【俗称：蚂蚁】
(62, '编织者', '蚂蚁', '核心、逃生', '1号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/weaver.png', '编织者可以非常轻松地躲开敌人，再找到合适的位置做出反击。他在敌方的视野中进进出出，还可以退回至之前的位置和生命状态，避开死亡的命运。这些躲避型技能可以确保他永远都是敌人心头的麻烦事。', '一、大招回到几秒前状态，保命神器；二、缩地隐身加速，追击逃跑；三、虫子减甲，配合物理输出。', '动力鞋、黑皇杖、代达罗斯之殇、蝴蝶', '克制：骚扰、持续输出（回溯保命）；怕：真眼、沉默、爆发'),
-- 63. 杰奇洛（智力 / 远程 / 复杂度1 / 4/5号位）【俗称：双头龙】
(63, '杰奇洛', '双头龙', '辅助、爆发、控制、推进', '4/5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/jakiro.png', '杰奇洛是他们自己最好的朋友。不满足于只用烈火惩治敌人，双生龙还将他们冻在原地，接受烈焰焚身。当敌人浑身着火时，他们转过身去吐出液态的火焰，对敌方建筑造成巨大的伤害。', '一、冰封路径控场，团战先手；二、大招铺火海，分割战场；三、技能都是 AOE，推线清野效率高。', '秘法鞋、阿哈利姆神杖、卫士胫甲、希瓦的守护', '克制：阵地战、推线（冰火 AOE）；怕：突脸、高机动'),
-- 64. 蝙蝠骑士（全才 / 远程 / 复杂度2 / 3号位）【俗称：蝙蝠】
(64, '蝙蝠骑士', '蝙蝠', '控制、逃生、先手', '3号位', '全才', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/batrider.png', '只要翱翔于天空，蝙蝠骑士可以从四面八方发动攻势。他手握拉索把敌人抓住，从树梢高飞而过，将猎物从一道火焰路径上拖到无情的盟友面前。', '一、大招拖人是核心，把敌人拖回队友中间；二、燃油叠加越烧越疼；三、跳刀切入，BKB 保证拖人成功。', '闪烁匕首、黑皇杖、阿哈利姆神杖、卫士胫甲', '克制：单核（大招拖人）；怕：打断、反手'),
-- 65. 陈（智力 / 远程 / 复杂度3 / 5号位）
(65, '陈', '', '辅助、推进', '5号位', '智力', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/chen.png', '每逢战斗就去丛林中劝化生物，陈率领着他的权宜之军援助战场上的队伍。让盟友远离危险的同时控制野兽袭击敌人。万念俱灰之际，无处不在的圣光还将带来一线生机。', '一、控制野怪参战，前期强势；二、大招全图加血救场；三、操作复杂，新手建议熟悉后再玩。', '秘法鞋、梅肯斯姆、卫士胫甲、支配头盔', '克制：前期压制、推进（野怪军团）；怕：后期乏力、操作门槛'),
-- 66. 幽鬼（敏捷 / 近战 / 复杂度2 / 1号位）【俗称：SPE】
(66, '幽鬼', 'SPE', '核心、肉盾、逃生', '1号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/spectre.png', '与幽鬼为敌就休想摆脱她的鬼影。她的存在可以笼罩整片战场，轻松毁灭落单的猎物。一旦让她完成力量的积聚，谁也逃不过她可怕的惩罚。', '一、大招全图支援和抓单，多关注小地图；二、反弹伤害让打她的人受伤；三、前期弱，发育为主，成型后全图压制。', '辉耀、黑皇杖、恐鳌之心、撒旦之邪力', '克制：后期全球流（大招降临）；怕：前期压制、单抓'),
-- 67. 末日使者（力量 / 近战 / 复杂度2 / 3号位）【俗称：末日、大恶魔】
(67, '末日使者', '末日、大恶魔', '核心、爆发、控制、肉盾、先手', '3号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/doom_bringer.png', '末日使者总有手段终结敌人。他吞噬生物并获得他们生前的各种技能，他的终极技能让敌人对自己的技能和物品望之兴叹，随之被魔火烧成灰烬。', '一、打团前先想好大招给谁——优先敌方核心或关键控制；二、出门就吃野怪，不同野怪给的技能不同，优先吃带控制的；三、自身较笨重，注意站位别被先手。', '先锋盾、闪烁匕首、黑皇杖、强袭胸甲', '克制：任何核心（大招废一人）；怕：被集火、净化'),
-- 68. 远古冰魄（智力 / 远程 / 复杂度2 / 5号位）【俗称：冰魂、AA】
(68, '远古冰魄', '冰魂、AA', '辅助、爆发、控制', '5号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/ancient_apparition.png', '远古冰魄可以在整片战场的任意位置降下毁灭性的冰暴，衰弱的敌人一旦中招，无论身处何地都将粉身碎骨。减速敌人的同时他还能提升盟友在战场上的出手效果，对于他的敌人而言，他始终是一个威胁。', '一、大招全图支援，预判放；二、冰冻期间无法回复，克制回血英雄；三、减速光环限制走位。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：奶妈、回复流（大招禁疗）；怕：突脸、脆皮'),
-- 69. 熊战士（敏捷 / 近战 / 复杂度1 / 1号位）【俗称：拍拍熊、拍拍】
(69, '熊战士', '拍拍熊、拍拍', '核心、控制、肉盾', '1号位', '敏捷', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/ursa.png', '熊战士每次挥爪都会让他的目标愈发脆弱。他可以短时间内加快出击的速度，放缓附近猎物的脚步，将敌人们快速撕碎。', '一、连拍叠加伤害，贴脸输出爆炸；二、前期就能单挑肉山，注意时机；三、怕风筝，跳刀和晕锤留人。', '相位鞋、闪烁匕首、黑皇杖、深渊之刃', '克制：单挑、打肉山（连拍叠伤）；怕：风筝、强控、减速'),
-- 70. 裂魂人（力量 / 近战 / 复杂度1 / 3/4号位）【俗称：白牛】
(70, '裂魂人', '白牛', '核心、控制、肉盾、逃生、先手', '3/4号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/spirit_breaker.png', '兼具极高的机动性和攻击性，裂魂人可以跨越整个地图发动冲刺，使敌人陷入战斗。手中沉重的灯笼痛击着敌人，每次敲出的重击让他们意识模糊。他的敌人可以逃，但是他们无处可藏。', '一、冲锋全图锁定敌人，多关注小地图找落单目标；二、大招冲撞后接普攻眩晕，先手控制足；三、节奏就是不断冲人建立优势，但也别冲进人群送死。', '相位鞋、先锋盾、黑皇杖、强袭胸甲', '克制：落单脆皮、法师（全图冲撞）；怕：反手控制、抱团'),
-- 71. 矮人直升机（敏捷 / 远程 / 复杂度1 / 1号位）【俗称：飞机】
(71, '矮人直升机', '飞机', '核心、爆发、控制', '1号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/gyrocopter.png', '矮人直升机直冲云霄，所有火力都已准备好随时开战。可以轰击周围所有敌人的机关炮弹，让他们应接不暇的火箭弹幕，只要让他积累了足够的力量，他就能轻而易举地毁灭敌人。', '一、火箭弹幕贴脸伤害极高，前期打架很强；二、大招支援远处队友；三、出装输出拉满，团战 AOE 拉满。', '黑皇杖、代达罗斯之殇、撒旦之邪力、蝴蝶', '克制：抱团（AOE 输出）；怕：突脸、爆发'),
-- 72. 炼金术士（力量 / 近战 / 复杂度1 / 1号位）【俗称：炼金】
(72, '炼金术士', '炼金', '核心、辅助、爆发、控制、肉盾、先手', '1号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/alchemist.png', '炼金术士在一击一杀中都能合成额外的资源，收集摧毁敌人的器具不在话下。腐蚀酸液和大量不稳定的化学药剂会让敌人措手不及。为了保证自己贪婪的劣迹不受打扰，他将力战到底。', '一、核心思路是刷：用酸雾清兵清野，补刀时留意被动给的额外金币；二、钱多了可以买阿哈利姆神杖"喂"给队友强化技能（Dota 特色机制）；三、大招提供回血回蓝和移速，打团前记得先开。注意炼金有点"虚胖"，被控住秒不掉优势。', '狂战斧、辉耀、强袭胸甲、阿哈利姆神杖（喂队友）', '克制：后期阵容（发育快）；怕：前期压制、末日使者大招'),
-- 73. 祈求者（智力 / 远程 / 复杂度3 / 2号位）【俗称：卡尔】
(73, '祈求者', '卡尔', '核心、爆发、控制、逃生、推进', '2号位', '智力', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/invoker.png', '祈求者可以随意施展脑海中复杂的法术，充分做到随机应变。三种魔法元素的任意组合都可以产生十大魔法之一，意味着他向来都是有条不紊地毁灭敌人或者逃离追杀。', '一、技能组合需要大量记忆和练习；二、前期火人/雷球发育，后期法术轰炸；三、新手建议人机练熟再上分。', '动力鞋、阿哈利姆神杖、黑皇杖、刷新球', '克制：全能型（10 种法术）；怕：沉默、前期压制'),
-- 74. 沉默术士（智力 / 远程 / 复杂度2 / 4号位）【俗称：沉默】
(74, '沉默术士', '沉默', '核心、辅助、爆发、控制、先手', '4号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/silencer.png', '沉默术士可以改变每次战斗的局势，有他在场，敌人无法自如地施放技能。他挥舞旋刃将敌人粉碎的同时还将夺取他们的智力，让他们永远难以翻身。', '一、大招全图沉默，团战时机关键；二、偷智力越打越强；三、诅咒让敌人放技能掉血。', '动力鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：法师（全图沉默）；怕：突脸'),
-- 75. 殁境神蚀者（智力 / 远程 / 复杂度2 / 2号位）【俗称：黑鸟、OD】
(75, '殁境神蚀者', '黑鸟、OD', '核心、爆发、控制', '2号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/obsidian_destroyer.png', '殁境神蚀者禁锢敌人后窃取其神智，将生人的智力转化为毁灭的力量。他运用奥术能量发动猛攻，他的终极冲击能粉碎敌人的心智，即使侥幸逃生也将被消去魔法。', '一、偷智力越打越强；二、大招对低智力英雄伤害爆炸；三、自身脆，注意保命道具。', '动力鞋、闪烁匕首、黑皇杖、希瓦的守护', '克制：低智力英雄、肉盾（智力差爆发）；怕：突脸、沉默'),
-- 76. 狼人（力量 / 近战 / 复杂度2 / 1/3号位）
(76, '狼人', '', '核心、肉盾、逃生、推进', '1/3号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/lycan.png', '或人或狼，狼人锋利的双爪和有力的下颚都是敌人的噩梦。他可以召唤隐形的战狼在前方侦察，或突袭敌人，他变身成狼后会获得极致的速度和力量，追杀敌人或在重重包围下逃出生天。', '一、狼群可以帮你看视野、带线、啃塔；二、变身时机很关键，变身后移速极快，追人和逃跑都靠它；三、节奏是带线牵制、找机会偷塔，团战打不过就带线，别硬刚。', '支配头盔、强袭胸甲、黑皇杖、否决坠饰', '克制：脆皮、推塔流；怕：AOE、正面硬团'),
-- 77. 酒仙（全才 / 近战 / 复杂度3 / 3号位）【俗称：熊猫、熊猫酒仙】
(77, '酒仙', '熊猫、熊猫酒仙', '核心、爆发、控制、肉盾、先手', '3号位', '全才', '近战', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/brewmaster.png', '酒仙在任何局势中的战斗力都不可小觑，他只要分裂成三个身怀绝技的元素战士往往就可以力挽狂澜。而在平时，他那减速的猛击和强大的棍技将使敌人陷入醉酒般的混乱中。', '酒仙（熊猫）是劣势路肉盾先手的代表：一、雷霆一击减速+让敌人打空，是换血神技；二、醉拳被动提供闪避和暴击，站得住又能打；三、大招"元素分离"分裂成三个元素熊猫（土、风、火），各带控制技能，本体分裂期间不会死——团战先放减速，再分裂进场搅乱阵型。记住：大招期间先操作风熊猫吹起对面核心。', '先锋盾、闪烁匕首、阿哈利姆神杖、黑皇杖', '克制：依赖普攻的近战核心（闪避+减速）；怕：魔法爆发、清场大招'),
-- 78. 暗影恶魔（智力 / 远程 / 复杂度2 / 5号位）【俗称：毒狗】
(78, '暗影恶魔', '毒狗', '辅助、爆发、控制、先手', '5号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/shadow_demon.png', '暗影恶魔可以放出魔性毒云伤害敌人，或侦察战场，胆敢接近他的敌人寥寥无几。将敌人放逐，给友军聚集的时间将其击杀，他还能召唤出敌人的幻象反攻敌人，在他身上施加恶魔的诅咒。', '一、禁锢队友救人或制造输出；二、大招克制有增益的敌人；三、技能时机关键，注意观察战场。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：救场、反手（禁锢）；怕：突脸'),
-- 79. 独行德鲁伊（敏捷 / 远程 / 复杂度3 / 1号位）【俗称：德鲁伊、熊德】
(79, '独行德鲁伊', '德鲁伊、熊德', '核心、肉盾、推进', '1号位', '敏捷', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/lone_druid.png', '独行德鲁伊与强大的熊灵并肩作战，敌军和他们的防御工事都会被熊掌碾压。必要时他施展变身之术在近战和远程攻击之间切换，只要他和他的伙伴获得了足够的力量，任何人都休想抵挡他们。', '一、熊灵是本体：给它出装，人和熊分开操作；二、拆塔极快，带线牵制；三、本体脆，注意藏好本体。', '相位鞋、强袭胸甲、黑皇杖、恐鳌之心（给熊灵出装）', '克制：推塔、带线（人熊双线）；怕：本体被切、AOE'),
-- 80. 混沌骑士（力量 / 近战 / 复杂度1 / 1号位）【俗称：混沌、CK】
(80, '混沌骑士', '混沌、CK', '核心、控制、肉盾、推进、先手', '1号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/chaos_knight.png', '混沌骑士独自成军。他可以召唤一队骑兵复制体粉碎敌人的防御工事，如果有敌人现身，他将现实撕裂，把他和他的幻象大军拉到目标身前，然后残酷的战棍会如同暴雨般落在目标的头上。', '一、大招幻象继承本体属性，开大后集火同一个目标爆发惊人；二、混沌之箭眩晕时间随机，拉到人后紧跟普攻；三、中期出臂章性价比极高。英雄缺刷钱手段，前期稳补刀很关键。', '臂章、黑皇杖、撒旦之邪力、强袭胸甲', '克制：单核阵容；怕：AOE 清幻象、控制'),
-- 81. 米波（敏捷 / 近战 / 复杂度3 / 2号位）【俗称：地卜师】
(81, '米波', '地卜师', '核心、爆发、控制、逃生、推进、先手', '2号位', '敏捷', '近战', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/meepo.png', '米波可以召唤多达四个永久复制体，使自己同时在多条战线上作战。他的分身四散在战场上，一旦找到敌人，他就会将其束缚，其余分身在爆炸性的传送中集合，然后将遇难者亲手埋葬。', '一、操作量极大，需要大量练习；二、分身共享等级，发育极快；三、一个分身死亡全灭，注意保护。', '动力鞋、闪烁匕首、黑皇杖、撒旦之邪力', '克制：刷钱快、多线操作；怕：AOE、单点爆发（杀一只全灭）'),
-- 82. 树精卫士（力量 / 近战 / 复杂度2 / 5号位）【俗称：大树、树】
(82, '树精卫士', '大树、树', '辅助、控制、肉盾、逃生、先手', '5号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/treant.png', '树精卫士永远是友善的盟友，他可以让同伴和高塔萌发恢复性的护甲。他在树林中不会显露踪迹，还可以用疯狂生长的植物束缚敌人，同时将敌人的生命渡给附近的盟友。', '一、被动靠近树隐身，做视野工作很安全；二、给防御塔回血是 Dota 特色，逆风时价值连城；三、大招缠绕配合队友 AOE，团战控制足。', '秘法鞋、梅肯斯姆、卫士胫甲、阿哈利姆神杖', '克制：保人、防守（塔回血）；怕：反隐、爆发'),
-- 83. 食人魔魔法师（力量 / 近战 / 复杂度1 / 4/5号位）【俗称：蓝胖】
(83, '食人魔魔法师', '蓝胖', '辅助、爆发、控制、肉盾、先手', '4/5号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/ogre_magi.png', '每次施法都有机会获得数倍的效果，食人魔魔法师只要稍微走点运就能将敌人烧成灰烬，或者提升队友的力量。当然，有时候运气还是很难把握的……', '一、嗜血术给大哥加攻速移速，团战前套上；二、多重施法纯看运气，晕到就是赚；三、本身非常肉，可以站前面吃伤害。', '秘法鞋、梅肯斯姆、洞察烟斗、阿哈利姆神杖', '克制：前期肉搏（多重施法看脸）；怕：后期乏力、被风筝'),
-- 84. 不朽尸王（力量 / 近战 / 复杂度1 / 5号位）【俗称：尸王】
(84, '不朽尸王', '尸王', '辅助、爆发、控制、肉盾', '5号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/undying.png', '蹒跚进入战场的不朽尸王将迫使敌人做出决定，到底是逃离他的愤怒，还是被愤怒撕裂。他可以吸取敌军的力量，召唤出一群拼命的亡灵。等到他最终变成魁梧的血肉傀儡，他的敌人早已被碾压殆尽。', '一、对线期很强势：腐烂贴脸消耗，压制对面核心；二、墓碑放的位置很关键，放好就是团战减速阵地；三、大招变大后更肉，团战顶前面。', '秘法鞋、梅肯斯姆、卫士胫甲、刃甲', '克制：对线压制（腐烂消耗）；怕：后期疲软、爆发'),
-- 85. 拉比克（智力 / 远程 / 复杂度3 / 4号位）【俗称：大魔导师】
(85, '拉比克', '大魔导师', '辅助、爆发、控制', '4号位', '智力', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/rubick.png', '拉比克总是在伺机窃取全新的法术，以彼之道还施彼身。他将敌人举向空中恣意丢弃，肆无忌惮地在毫无防备的敌人之中散布混乱。', '一、大招偷关键技能（如黑洞、毁灭），偷好能翻盘；二、念力控制敌人位置；三、观察对面技能冷却，偷最值的。', '闪烁匕首、阿哈利姆神杖、卫士胫甲、玲珑心', '克制：偷关键大招（以彼之道还施彼身）；怕：突脸、被集火'),
-- 86. 干扰者（智力 / 远程 / 复杂度2 / 5号位）【俗称：萨尔】
(86, '干扰者', '萨尔', '辅助、爆发、控制、先手', '5号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/disruptor.png', '干扰者尤其擅长搅乱敌人的计划。他可以召唤无法逾越的围栏困住目标，降下一阵使人沉默的风暴，如果敌人发动突袭，他还可以直接将对手往回传送。', '一、大招范围沉默，团战核心技能；二、把敌人拉回原点，克制位移英雄；三、配合队友 AOE，控制链拉满。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：法师、位移英雄（大招沉默）；怕：突脸、被先手秒'),
-- 87. 司夜刺客（全才 / 近战 / 复杂度2 / 4号位）【俗称：小强】
(87, '司夜刺客', '小强', '爆发、控制、逃生、先手', '4号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/nyx_assassin.png', '司夜刺客永远都在猎杀脆弱的目标。他无形地潜行在丛林中，寻找着他的猎物，他运用致命的利爪偷袭他们，刺人的尖刺让他们动弹不得，反弹的外壳还可以逆转一切反击。', '一、反伤甲让法系打你反而疼；二、隐身游走抓法师；三、尖刺穿人眩晕，先手控制。', '秘法鞋、阿哈利姆神杖、洞察烟斗、卫士胫甲', '克制：法师（反伤甲）；怕：真眼、物理爆发'),
-- 88. 娜迦海妖（敏捷 / 近战 / 复杂度2 / 1号位）【俗称：小娜迦、娜迦】
(88, '娜迦海妖', '小娜迦、娜迦', '核心、辅助、控制、逃生、推进、先手', '1号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/naga_siren.png', '娜迦海妖派出镜像的复制体攻击敌人，诱捕敌人将他们斩落，带领友军走向胜利。她还可以运用自己的嗓音，镇住周围的敌人，发动奇袭或组织快速的撤离。', '一、幻象分开刷钱和带线，经济起飞；二、大招沉睡敌人，用来撤退或开团；三、网住敌人配合集火。', '辉耀、黑皇杖、蝴蝶、恐鳌之心', '克制：带线牵制、团战睡人；怕：AOE、真眼'),
-- 89. 光之守卫（智力 / 远程 / 复杂度2 / 4/5号位）【俗称：光法、老头】
(89, '光之守卫', '光法、老头', '辅助、爆发、控制', '4/5号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/keeper_of_the_light.png', '对于任何团队而言光之守卫都是坚实的后盾。敌友的魔法均在他掌控之下，弱小的敌人将在光芒的冲击下轻易毁灭，而他进入灵魂形态后还能召集团队发动奇袭。', '一、查克拉给大哥回蓝，线上续航；二、大招白天强化技能，注意昼夜；三、飞马推线，后期带线牵制。', '秘法鞋、阿哈利姆神杖、卫士胫甲、玲珑心', '克制：消耗、保人（回蓝）；怕：突脸、真眼'),
-- 90. 艾欧（全才 / 远程 / 复杂度3 / 5号位）【俗称：小精灵、IO】
(90, '艾欧', '小精灵、IO', '辅助、爆发、逃生', '5号位', '全才', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/wisp.png', '艾欧生来就能让盟友力量倍增。身为强大的伙伴，精灵施展系链可以使盟友加速，敌人停滞。将战友连接并且在战场上任意传送，艾欧可以让危险的盟友更加致命。', '一、链接挂在核心队友身上，跟着他走，提供回血和移速；二、大招可以带一个人全图飞，配合队友抓人或救场；三、本体非常脆，站位藏好别暴露。艾欧极度依赖配合，建议开黑时玩。', '梅肯斯姆、卫士胫甲、圣洁吊坠、洞察烟斗', '克制：配合大哥（链接增益）；怕：本体被切、真眼反隐'),
-- 91. 维萨吉（全才 / 远程 / 复杂度3 / 3号位）【俗称：死灵飞龙、死灵龙】
(91, '维萨吉', '死灵飞龙、死灵龙', '辅助、爆发、控制、肉盾、推进', '3号位', '全才', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/visage.png', '当维萨吉的夺命佣兽在战场上四处侦察时，他将自己包藏在护甲中，寻找着战机。一旦周围出现战斗，他从附近战士所受的伤害中收集灵魂能量，再将其释放，完成毁灭性一击。', '一、魔宠操作是核心，人宠配合；二、护甲高，耐打；三、操作复杂，新手谨慎。', '秘法鞋、阿哈利姆神杖、卫士胫甲、强袭胸甲', '克制：肉盾、阵地（魔宠作战）；怕：AOE、操作门槛'),
-- 92. 斯拉克（敏捷 / 近战 / 复杂度2 / 1号位）【俗称：小鱼人】
(92, '斯拉克', '小鱼人', '核心、爆发、控制、逃生', '1号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/slark.png', '扑向重重险境，再悄悄地溜回来，这就是斯拉克的看家本领。他可不会放过困住落单敌人的机会，每一次出手都能让他们的实力减退，如果见势不妙他立马就能消失得无影无踪。', '一、被动偷属性，越打越强，别怂；二、大招隐身回血，残血绕一圈又满血；三、怕真眼和范围控制，注意切入时机。', '相位鞋、黑皇杖、撒旦之邪力、斯嘉蒂之眼', '克制：单挑、滚雪球（偷属性）；怕：真眼、范围控制'),
-- 93. 美杜莎（敏捷 / 远程 / 复杂度1 / 1号位）【俗称：大娜迦、蛇发女妖】
(93, '美杜莎', '大娜迦、蛇发女妖', '核心、控制、肉盾', '1号位', '敏捷', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/medusa.png', '美杜莎的奥义就是持久的输出。她运用魔法盾抵挡袭击的同时，分裂的箭矢将扫射接踵而至的敌人。到了实力雄厚的时候，她将成为一股阻止任何人前进的力量。', '一、魔法就是血量：蓝量管理是核心；二、分裂箭清线打团两不误；三、前期弱，队友保你发育，成型后接管比赛。', '蝴蝶、黑皇杖、撒旦之邪力、代达罗斯之殇', '克制：后期一打五（魔法护盾）；怕：前期压制、烧蓝（敌法师）'),
-- 94. 巨魔战将（敏捷 / 远程 / 复杂度2 / 1号位）【俗称：巨魔】
(94, '巨魔战将', '巨魔', '核心、控制、肉盾、推进', '1号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/troll_warlord.png', '巨魔战将可以在近战和远程攻击之间切换自如，无论远近他都是强大的力量。有着双斧在手，他的出击往往伴随着风暴般的旋刃。敌人很难抵挡他愈发迅捷的攻击，而他无论身在何方都可以帮助盟友发动猛击。', '一、攻速叠加机制，站桩输出极强；二、大招全队狂暴，开团神器；三、怕控制，BKB 必备。', '黑皇杖、撒旦之邪力、深渊之刃、蝴蝶', '克制：单挑、打肉山；怕：风筝、控制'),
-- 95. 半人马战行者（力量 / 近战 / 复杂度1 / 3号位）【俗称：人马】
(95, '半人马战行者', '人马', '爆发、控制、肉盾、逃生、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/centaur.png', '半人马战行者可谓是伤敌抗敌的大师。战斗中他一马当先，践踏地面眩晕敌人，每次受到攻击都能马上反击。他发动狂奔可以使盟友在进退中都跑得飞快，大大加快了杀戮的节奏。', '一、核心节奏是跳刀进场 + 马蹄践踏先手晕人，队友跟上输出；二、双刃剑伤害高但伤己，留着收残血；三、大招给全队加速，开团追人或集体撤退都好用。', '先锋盾、闪烁匕首、刃甲、恐鳌之心', '克制：脆皮后排（跳踩先手）；怕：被集火、百分比伤害'),
-- 96. 马格纳斯（全才 / 近战 / 复杂度2 / 3号位）【俗称：猛犸】
(96, '马格纳斯', '猛犸', '爆发、控制、逃生、先手', '3号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/magnataur.png', '愚蠢到成群结队的敌人将明白马格纳斯长角的恐怖。他身怀聚拢周围敌人的本领，运用强化的攻击毁灭他们，或者用他的长角将他们顶到无情的友军面前。', '一、先手连招是跳刀进场 + 大招吸人，队友 AOE 跟上；二、震荡波伤害可观，对线期消耗；三、授予力量给大哥加分裂攻击，团战前给队友套上。', '闪烁匕首、黑皇杖、刷新球、强袭胸甲', '克制：抱团阵容（大招吸人）；怕：被先手打断、沉默'),
-- 97. 伐木机（力量 / 近战 / 复杂度2 / 3号位）
(97, '伐木机', '', '爆发、肉盾、逃生', '3号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/shredder.png', '难以捉摸又疯不可测，伐木机的临敌往往伴随着丛林的倒下。各式锯片可以将敌人砍成碎末，他依靠锯链飞到附近的树上，向沿途的敌人带去猛烈的伤害。', '一、围绕树打：锯齿飞轮和钩爪都需要树，别在空地打架；二、钩爪可以钩树位移，逃跑追击都靠它；三、前期伤害极高，对线期可以打得非常凶。', '血精石、黑皇杖、恐鳌之心、希瓦的守护', '克制：近战、低机动（树林战）；怕：控制、纯魔法爆发'),
-- 98. 钢背兽（力量 / 近战 / 复杂度1 / 3号位）【俗称：刚背兽、屁股】
(98, '钢背兽', '刚背兽、屁股', '核心、爆发、肉盾、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/bristleback.png', '只要是打架，钢背兽确实会全背以赴。他大大咧咧地介入战斗，丝毫不担心背后和侧面的伤害，再将伤害性的刺针和减速的鼻涕喷向敌人。', '一、永远用背对着敌人，正面其实很脆；二、针刺叠加层数越高伤害越疼，追人时保持喷刺；三、出先锋盾和刃甲，站队伍最前面吃伤害搅乱阵型。最怕被沉默或风筝，鼻涕减速要用来黏人。', '先锋盾、刃甲、辉耀、撒旦之邪力', '克制：近战阵容（反伤）；怕：白银之锋破甲、控制'),
-- 99. 巨牙海民（力量 / 近战 / 复杂度1 / 4号位）【俗称：海民、雪人】
(99, '巨牙海民', '海民、雪人', '爆发、控制、先手', '4号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/tusk.png', '巨牙海民总是斗志昂扬。他可以创造一道碎冰之墙马上困住敌人，召集友军进入巨大的雪球向敌人滚去，近身后再祭出招牌的淘汰之拳。', '一、冰封碎片封路要放得刁钻，把敌人和退路隔开；二、大招踢起敌人配合队友集火；三、雪球可以带队友一起滚过去开团，先手神器。', '相位鞋、闪烁匕首、黑皇杖、洞察烟斗', '克制：脆皮（大招先手）；怕：沉默、被反打'),
-- 100. 天怒法师（智力 / 远程 / 复杂度1 / 4/5号位）【俗称：天怒】
(100, '天怒法师', '天怒', '辅助、爆发、控制', '4/5号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/skywrath_mage.png', '无比致命又异常脆弱，天怒法师操控强大的魔法对敌人发动狂轰滥炸，将他们快速消灭。敌人经他沉默后对魔法全无抵抗，也就是说谁敢反抗他都会被轻而易举地汽化。', '一、技能连招爆发，练好命中；二、沉默克制法师；三、自身极脆，站位最重要。', '秘法鞋、阿哈利姆神杖、闪烁匕首、卫士胫甲', '克制：脆皮（爆发秒人）；怕：突脸、反手'),
-- 101. 亚巴顿（全才 / 近战 / 复杂度1 / 3/5号位）【俗称：死骑、地狱领主】
(101, '亚巴顿', '死骑、地狱领主', '核心、辅助、肉盾', '3/5号位', '全才', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/abaddon.png', '敌之尖刀，我之伤药，亚巴顿无论受到何种袭击都能幸免于难。他随时准备奔入焦灼的战场中盾护盟友，向敌友释放疗己或伤人的缠绕。', '一、无光之盾不仅能挡伤害，给队友套还能移除负面状态——看到队友被晕立刻给盾；二、大招血量低于阈值自动触发，触发期间挨打反而回血，别怂；三、别把大招浪费在必死的局面，它更适合反打。', '梅肯斯姆、卫士胫甲、阿哈利姆神杖、辉耀', '克制：控制型敌人（护盾解控）；怕：爆发秒杀、末日大招'),
-- 102. 上古巨神（力量 / 近战 / 复杂度2 / 4/5号位）【俗称：大牛】
(102, '上古巨神', '大牛', '爆发、控制、肉盾、先手', '4/5号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/elder_titan.png', '用灵体游魂探明敌情后，上古巨神从任意方向发动突袭。他巨蹄的重踏可以让敌人停下，他的存在则蚕食敌人的防御，而他还能撕裂大地本身，使敌人一一倒下。', '一、灵体放出去多碰敌人，回来时给自己加攻击，碰得越多越强；二、大招有延迟，配合队友控制或封走位使用；三、光环减甲让队友物理输出大增，跟紧大哥。', '秘法鞋、梅肯斯姆、卫士胫甲、阿哈利姆神杖', '克制：高护甲阵容（减甲）、抱团；怕：高机动、爆发'),
-- 103. 军团指挥官（力量 / 近战 / 复杂度1 / 3号位）【俗称：军团、LC】
(103, '军团指挥官', '军团、LC', '核心、爆发、控制、肉盾、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/legion_commander.png', '军团指挥官席卷整片战场，与落单的敌人一一单挑。每次决斗获胜后她出手的力量便增强一分，最后她就可以成为毫不留情的伊人之军。', '一、决斗前确保打得过——先消耗或等队友控制；二、每赢一次决斗永久加攻，节奏就是"抓单→变强→再抓单"；三、出刃甲和跳刀，跳决斗是标准先手。注意：输了会给对方加攻，别上头。', '刃甲、闪烁匕首、黑皇杖、强袭胸甲', '克制：脆皮、落单英雄（决斗抓单）；怕：决斗打不过、被集火'),
-- 104. 灰烬之灵（敏捷 / 近战 / 复杂度2 / 2号位）【俗称：火猫】
(104, '灰烬之灵', '火猫', '核心、爆发、控制、逃生、先手', '2号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/ember_spirit.png', '身手矫捷，飘忽不定；出手迅速，无人幸免；阳炎长索，破阵缚敌；爆裂残像，瞬息飞至；烬灵之焰，难捕难防。', '一、练好火猫需要大量练习，新手慎重；二、无影拳配合队友控制（如冰女冰冻）伤害爆炸；三、残影可以保命，打不过就飞走。', '动力鞋、黑皇杖、代达罗斯之殇、斯嘉蒂之眼', '克制：脆皮、团战（无影拳）；怕：沉默、强控'),
-- 105. 大地之灵（力量 / 近战 / 复杂度3 / 4号位）【俗称：土猫】
(105, '大地之灵', '土猫', '爆发、控制、肉盾、逃生、先手', '4号位', '力量', '近战', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/earth_spirit.png', '大地之灵能使众敌乱成一团，战友斗志昂扬。无论战情如何，他都可以来回发动他的残像，对敌人造成伤害，或者将盟友从鬼门关的边缘抓回来。', '一、新手先在人机练好"放石头—踢/拉"的基本连招再上分；二、前期游走效率极高，多帮中路建立优势；三、团战用巨石翻滚进场，大招贴住多人持续减速。技能耗残岩，注意石头数量。', '静谧之鞋、闪烁匕首、黑皇杖、洞察烟斗', '克制：脆皮、无位移英雄；怕：沉默、残岩管理失误'),
-- 106. 恐怖利刃（敏捷 / 近战 / 复杂度2 / 1号位）【俗称：TB、魂守】
(106, '恐怖利刃', 'TB、魂守', '核心、爆发、推进', '1号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/terrorblade.png', '恐怖利刃的存在将使战局无法估量。他召唤的强大幻象可以迷惑敌人，撕扯他们的防线。恶魔掠夺者还可以与敌友交换血量，轻松地避开死亡或削弱敌人的力量。', '一、大招换血反杀，残血也能赢；二、幻象刷钱带线；三、变身时机关键，团战和拆塔两用。', '黑皇杖、蝴蝶、撒旦之邪力、恐鳌之心', '克制：拆塔、单挑（大招换血）；怕：法系爆发、控制'),
-- 107. 凤凰（力量 / 远程 / 复杂度2 / 3/5号位）
(107, '凤凰', '', '辅助、爆发、控制、逃生、先手', '3/5号位', '力量', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/phoenix.png', '凤凰冲入战斗，运用阳炎光线冲击敌人，治疗战友。到了适当时机，它可以化成一个燃烧的恒星，灼烧周围的仇敌，接着释放出令人眩晕的爆炸，使自己重获新生。', '一、技能耗血，注意血量管理；二、大招变蛋后队友要保护蛋，蛋被打破会死；三、炎阳冲击范围伤害极高，团战抱团时效果爆炸。', '静谧之鞋、阿哈利姆神杖、黑皇杖、恐鳌之心', '克制：抱团阵容（大招范围伤害）；怕：拆蛋、沉默、点爆发'),
-- 108. 神谕者（智力 / 远程 / 复杂度3 / 5号位）【俗称：神谕】
(108, '神谕者', '神谕', '辅助、爆发、控制、逃生', '5号位', '智力', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/oracle.png', '将手中复杂的技能经过仔细的融合，神谕者同时操控着队友和对手的命运。他将命在旦夕的盟友笼罩在虚妄的诺言中，给予其宝贵的时间将敌人毁灭，甚至还能逆转必死的命数。', '一、技能组合复杂，新手需练习；二、大招期间队友不死，保大哥神器；三、注意技能副作用，别坑队友。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：保人、克制控制（技能解控）；怕：爆发、操作门槛'),
-- 109. 工程师（全才 / 远程 / 复杂度2 / 4号位）【俗称：炸弹人、炸弹】
(109, '工程师', '炸弹人、炸弹', '爆发、控制', '4号位', '全才', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/techies.png', '对工程师而言，战斗就是搞恶作剧。嘻嘻哈哈地在战场上抛出粘性炸弹，他们隐形的爆炸地雷、让敌人束手束脚的电击还有英勇无畏的爆破攻击都足以让大多数敌人丢掉性命。或至少大发雷霆。往往两者兼有。', '一、地雷布防关键位置，视野和骚扰；二、自爆伤害高，注意时机；三、团战输出有限，偏运营节奏。', '秘法鞋、阿哈利姆神杖、卫士胫甲、玲珑心', '克制：地图控制、防守（埋雷）；怕：真眼、真视宝石'),
-- 110. 寒冬飞龙（智力 / 远程 / 复杂度2 / 5号位）【俗称：冰龙、冬龙】
(110, '寒冬飞龙', '冰龙、冬龙', '辅助、爆发、控制', '5号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/winter_wyvern.png', '寒冬飞龙在天空上翱翔无阻，她掠过战场之时运用灼热的寒意减速敌人。如果敌人蠢到成群结队，他们将领教寒冰碎片的爆炸滋味，还有向盟友倒戈相向的可怕诅咒。', '一、冰封队友无敌，救大哥神器；二、大招让敌人互相攻击，时机关键；三、减速风筝，团队型打法。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：物理阵容（冰封保护）、反手；怕：突脸'),
-- 111. 天穹守望者（全才 / 远程 / 复杂度3 / 1号位）【俗称：电狗、泽特】
(111, '天穹守望者', '电狗、泽特', '核心、爆发、逃生', '1号位', '全才', '远程', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/arc_warden.png', '原初力量的细小碎片，与遗迹们系出同源，天穹守望者泽特誓将见证天辉和夜魇大战的终结。操控乱流能量突袭落单的敌人，或者扭曲空间，制造力场保护盟友。召唤闪光幽魂来回萦绕，摧残踏足的敌人，然后创造泽特的复制体，控制所有的物品和技能，将众敌全数碾压。', '一、学习成本高，新手建议人机熟悉；二、分身继承装备，后期"两个大哥"一起输出；三、本体和分身分开发育，注意别都死了。', '迈达斯之手、飓风长戟、黑皇杖、撒旦之邪力', '克制：后期（分身双核）；怕：前期压制、单抓'),
-- 112. 孽主（力量 / 近战 / 复杂度2 / 3号位）【俗称：深渊领主】
(112, '孽主', '深渊领主', '辅助、爆发、控制、肉盾、逃生', '3号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/abyssal_underlord.png', '召唤成波深渊之焰，焚祭在恶意掌控中无力还手的敌人。战斗的屠戮是场盛宴，敌人的消亡将会带来力量，他们的攻势在你面前不值一提。在现实中撕出一道裂隙，将自己和友军全屏传送，胆敢蔑视孽主意志的人，维洛格罗斯将奉上血腥的报应。', '一、大招可以把全队传送到地图任意位置，抓人救场偷家都行；二、火雨清线极快，带线牵制是本职；三、被动光环让附近敌人输出下降，站前面就行。', '卫士胫甲、辉耀、洞察烟斗、恐鳌之心', '克制：带线牵制、全图支援（大招）；怕：正面硬团'),
-- 113. 齐天大圣（敏捷 / 近战 / 复杂度2 / 1/2号位）【俗称：大圣】
(113, '齐天大圣', '大圣', '核心、控制、逃生、先手', '1/2号位', '敏捷', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/monkey_king.png', '为了随时痛快地打上一架，齐天大圣行走于树顶之上。只为从浓密的树叶中跃出，给敌人一场惊喜。唤来一帮猴子猴孙碾压对手，这个敏捷的魔术师陶醉在战场的混乱中，随时都会用他的金箍棒击碎所有逃跑的美梦。', '一、跳树移动和伏击，抓人突然；二、棒击大地伤害高，练好连招；三、大招圈内强化，团战阵地战强。', '碎颅锤、黑皇杖、代达罗斯之殇、深渊之刃', '克制：脆皮、阵地战（大招圈地）；怕：控制、爆发'),
-- 114. 石鳞剑士（全才 / 近战 / 复杂度2 / 3号位）【俗称：滚滚】
(114, '石鳞剑士', '滚滚', '核心、爆发、控制、肉盾、逃生、先手', '3号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/pangolier.png', '渴望随时冲入危险，石鳞剑士擅长干扰敌人的行动，将自己置身于混乱之中。巧妙地运剑刺入护甲的缝隙之中，再利用他厚实的鳞片摆脱攻击，这位优雅的剑客时刻准备着滚进战场。', '一、大招滚动期间魔免，冲乱敌方阵型；二、被动减甲，配合队友物理输出；三、机动性强，先手撤退都行。', '秘法鞋、阿哈利姆神杖、黑皇杖、玲珑心', '克制：阵型搅局（大招滚动）；怕：沉默、点控'),
-- 115. 邪影芳灵（智力 / 远程 / 复杂度2 / 4号位）【俗称：花仙子】
(115, '邪影芳灵', '花仙子', '辅助、爆发、控制、逃生', '4号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/dark_willow.png', '在阴影中微微振翅，也许这就是敌人眼中的邪影芳灵，她躲避追击，操控狡猾的仙灵法术控制敌人的行动。召唤远比书上的魔法更为古老的力量，她将敌人束缚在原地，再将仙灵之境的所有怒火和恐怖全数释放。', '一、诅咒叠加后爆发惊人；二、大招恐惧敌人，团战搅局；三、自身脆，注意站位。', '秘法鞋、阿哈利姆神杖、否决坠饰、玲珑心', '克制：脆皮（诅咒爆发）；怕：真眼、突脸'),
-- 116. 天涯墨客（智力 / 远程 / 复杂度2 / 4号位）【俗称：墨客】
(116, '天涯墨客', '墨客', '辅助、爆发、控制、逃生', '4号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/grimstroke.png', '擅长从远处操控战斗，天涯墨客洞察所有动向，评定所有路线，决定何时从如墨的黑暗中现身控制对手，挥毫将他们一同束缚。他喜爱释放幻影的奴隶侵扰对手，而自己就慎重考虑，怎样给众多敌人写下最后一笔。', '一、大招绑定两个敌人，伤害共享；二、墨迹沉默连线，克制突进；三、配合队友 AOE，团战放大器。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：抱团（灵魂绑定）；怕：突脸'),
-- 117. 玛尔斯（力量 / 近战 / 复杂度1 / 3号位）
(117, '玛尔斯', '', '核心、控制、肉盾、先手', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/mars.png', '战士的神明玛尔斯在冲突的中心傲然挺立，在致命的坚盾掩护之下他传奇的战矛刺穿敌人。在余烬军团的忠实成员环绕的竞技场中，他陶醉于对手的决战之中，而他们将确保无人可以临阵脱逃，而不论他面临何种危机，战神都能化险为夷，因为他知道众人都站在他这边。', '一、大招圈住敌方关键人物，队友在圈外输出；二、神之遣戒把敌人钉在树上或竞技场边缘，接大招效果最佳；三、正面减伤让他非常耐打，站在队伍前面顶线。', '先锋盾、闪烁匕首、黑皇杖、强袭胸甲', '克制：物理阵容（正面减伤）；怕：法系爆发、破甲'),
-- 118. 虚无之灵（全才 / 近战 / 复杂度2 / 2号位）【俗称：紫猫】
(118, '虚无之灵', '紫猫', '核心、爆发、控制、逃生', '2号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/void_spirit.png', '掌握着足以粉碎凡人心智的秘密，虚无之灵自他的隐之圣堂现身，同时守卫着战场上多片区域。他能够随时出入凡间，让对手疲于奔命，从任何希望的地点出手，必要之时召唤太虚的力量保护自己。', '一、穿梭位移灵活，切入切出；二、爆发连招练好；三、定位刺客型中单。', '动力鞋、黑皇杖、闪烁匕首、希瓦的守护', '克制：脆皮（虚空穿梭爆发）；怕：沉默、控制'),
-- 119. 电炎绝手（全才 / 远程 / 复杂度1 / 4/5号位）【俗称：奶奶、老奶奶】
(119, '电炎绝手', '奶奶、老奶奶', '辅助、爆发、控制、逃生', '4/5号位', '全才', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/snapfire.png', '乐于用她信赖的猎枪轰掉你的腿，也同样乐于用可口又危险的饼干封上你的嘴，电炎绝手碧翠丝非常高兴地与她的龙蜥小莫迪一同驾临战场，时刻准备着用她自制的火炮摧残他们的敌人，或者用小莫迪的密集火痰毁灭他们。', '一、饼干可以把队友弹射出去，救人和开团都行；二、大招远程炮击支援远处战场；三、喷火炮近距离爆发高，站位别太靠后浪费输出。', '秘法鞋、梅肯斯姆、阿哈利姆神杖、刷新球', '克制：远程支援（全图炮击）；怕：突脸、被先手'),
-- 120. 森海飞霞（敏捷 / 远程 / 复杂度2 / 4号位）【俗称：松鼠、小松鼠】
(120, '森海飞霞', '松鼠、小松鼠', '辅助、爆发、控制、逃生', '4号位', '敏捷', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/hoodwink.png', '麻烦来临时森海飞霞总是身在左近，她的生活就是与自己视为家乡的诡异林渊中充斥的威胁纠缠不清。 携带着巨大的弩机，同时仍能在密林中轻松奔走，森海飞霞在战斗中来去自如。只要有一瞬间没见到她，她就会从你背后现身——而你目瞪口呆的尸体已经挂在她的一张网里。', '一、利用树林移动和隐身，打了就跑；二、坚果眩晕可弹射，封走位；三、大招远程狙击，收残血支援两不误。', '秘法鞋、阿哈利姆神杖、否决坠饰、玲珑心', '克制：丛林游击、单抓；怕：真眼、反隐'),
-- 121. 破晓辰星（力量 / 近战 / 复杂度1 / 3号位）【俗称：破晓】
(121, '破晓辰星', '破晓', '核心、肉盾', '3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/dawnbreaker.png', '破晓辰星在战场的中央散发着万丈光芒，她乐于挥舞来自上界的战锤粉碎敌军，治疗附近的盟友。她也沉醉于将手中巨大的武器抛向敌阵，再与她的战锤在一道炽烈的尾迹中会合，她时刻等待着运用真正的宇宙之力飞去援助她的战友——不论她的敌人身在战场何处都将迎来溃败。', '一、大招可以全图飞向队友，团战爆发时及时支援；二、二技能旋转期间魔免，用来躲控制；三、对线用一技能清兵消耗，出装半肉半输出，站得住才能持续回血。', '先锋盾、碎颅锤、黑皇杖、恐鳌之心', '克制：抱团阵容（全图支援）；怕：持续伤害、技能被打断'),
-- 122. 玛西（全才 / 近战 / 复杂度2 / 4号位）
(122, '玛西', '', '核心、辅助、控制、逃生、先手', '4号位', '全才', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/marci.png', '玛西证明了永恒的忠诚会带来无与伦比的力量，她进入战场时早已准备好高举拳头来捍卫她的伙伴们。她能轻松地抛起战场周围的敌友，也很乐意跃入任何战斗，为友军带来致命的优势，还能释放出潜藏的力量，就连神明也要重新考虑与她作对是否明智。', '一、一技能抓取可以把队友扔进战场（也可以扔走救人）；二、二技能跳到敌人身后接眩晕，是她的先手连招；三、大招狂暴期间平 A 附带额外伤害，配合队友集火同一目标。', '相位鞋、碎颅锤、黑皇杖、强袭胸甲', '克制：脆皮、单核（先手扔人）；怕：控制、风筝'),
-- 123. 獸（力量 / 近战 / 复杂度1 / 2/3号位）【俗称：原始兽、野兽】
(123, '獸', '原始兽、野兽', '控制、肉盾、先手', '2/3号位', '力量', '近战', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/primal_beast.png', '在敌友之间野蛮冲撞，獸如同天性闹腾一般奔入战场。在何种战斗中獸都是无法回避的威胁，他可以惩戒攻击者，喜欢抓起猎物反复向地面捶击，直到战场只剩下肉泥。', '一、冲锋可以蓄力，切入时机看准再放；二、大招抓住敌人往队友方向摔，配合集火；三、被动叠加让他越战越勇，前期打架能力强，积极游走。', '先锋盾、黑皇杖、闪烁匕首、恐鳌之心', '克制：脆皮、落单（冲撞开团）；怕：控制链、风筝'),
-- 124. 琼英碧灵（智力 / 远程 / 复杂度1 / 1/2号位）【俗称：穆尔塔、琼英】
(124, '琼英碧灵', '穆尔塔、琼英', '核心、爆发、控制', '1/2号位', '智力', '远程', 1, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/muerta.png', '琼英碧灵漫步于生者的土地，主宰着死亡，她利用骇人的花式枪弹和召唤的亡魂困住目标，将敌人完全扼杀。她总是准备好用手上备用的枪来解决大意的目标，当她穿越生死之界，用恶灵的超凡愤怒打击敌人，那就是她凶相毕露之时。', '一、形态切换是核心机制，练好节奏；二、大招期间输出爆炸，时机关键；三、怕控制，BKB 保命。', '动力鞋、黑皇杖、代达罗斯之殇、蝴蝶', '克制：爆发、阵地战（形态切换）；怕：控制、突脸'),
-- 125. 百戏大王（智力 / 远程 / 复杂度2 / 4号位）
(125, '百戏大王', '', '辅助、爆发、控制、逃生', '4号位', '智力', '远程', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/ringmaster.png', '整个战场就是一个舞台，而百戏大王正是欢腾的导演。百戏大王利用表演家的架势操控战斗，手中可怕的长鞭和无尽的飞刀可以驯服敌人，狡猾的逃脱表演能将盟友带离危险 ，而且他总能勉强观众去观看迷人的奇观转轮。', '一、技能多样，注意连招顺序；二、控制技能开团，辅助队友；三、保命技能救人，团队型打法。', '秘法鞋、阿哈利姆神杖、卫士胫甲、洞察烟斗', '克制：控制、救场（马戏技能组合）；怕：突脸'),
-- 126. 凯（敏捷 / 近战 / 复杂度3 / 1/2号位）
(126, '凯', '', '核心、控制、逃生', '1/2号位', '敏捷', '近战', 3, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/kez.png', '说到作战的策略，凯更乐于率性而为——他可以根据战场上的需求在他的长刀和双钗之间自如地切换，劈砍、冲刺、突袭和招架都是信手拈来。但只要他全神贯注，他可以应对所有可能的情况，选好合适的工具再提前一点计划就能出击、逃跑或者智取敌人。', '一、技能需要两种形态切换，新手先练熟连招；二、机动性强，追击逃跑都出色；三、定位灵活，出装跟着局势走。', '动力鞋、黑皇杖、代达罗斯之殇、蝴蝶', '克制：脆皮（双刀连斩）；怕：控制、不熟练'),
-- 127. 朗戈（力量 / 近战 / 复杂度2 / 4/5号位）
(127, '朗戈', '', '辅助、控制、肉盾', '4/5号位', '力量', '近战', 2, 'https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/largo.png', '凭借灵巧的手指和灵活的舌头，朗戈随时都能驱散敌友，用恰到好处的乐曲为他的团队提供伤害，治疗，或加速。', '朗戈是带"演奏"机制的新辅助：一、动人之舐可以把队友拉回身边（救人或开团），还能净化负面状态；二、蛙力千钧的范围伤害+减速用来消耗和断后；三、大招"两栖狂想曲"开启后技能栏会切换成三首乐曲：疾步生风（加速）、巨腹闪电战（伤害）、大屿灵药（回复），根据战局切歌；四、先天技能"安可"让给队友施放的增益也作用于自己。新手先练"拉人"的时机。', '静谧之鞋、原力法杖、微光披风、洞察烟斗', '克制：贴脸近战（拉人风筝）；怕：沉默（按不出技能）、集火');

-- ============ 校验：应看到 127 行 ============
SELECT COUNT(*) AS hero_total FROM hero;
-- 主属性分布：力量 36 / 敏捷 35 / 智力 34 / 全才 22
SELECT attr, COUNT(*) FROM hero GROUP BY attr;
-- 复杂度分布
SELECT complexity, COUNT(*) FROM hero GROUP BY complexity;
-- 俗称别名覆盖率（约 100 名英雄有俗称/旧名）
